struct deadline { struct timespec at; };   /* CLOCK_MONOTONIC, set once at ingress */
static long remaining_ms(const struct deadline *d) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (d->at.tv_sec - now.tv_sec) * 1000L
         + (d->at.tv_nsec - now.tv_nsec) / 1000000L;
}
/* each hop forwards the same deadline; every wait uses what is left */
long t = remaining_ms(&req->deadline);
if (t <= 0) return DEADLINE_EXCEEDED;
int n = poll(fds, nfds, (int)t);          /* relative ms, never a fresh full timeout */
